import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.util.Arrays;

import org.newsclub.net.unix.AFUNIXServerSocketChannel;
import org.newsclub.net.unix.AFUNIXSocketChannel;
import org.newsclub.net.unix.AFUNIXSocketAddress;

public class Repro2 {
  static void test(String label, boolean directRead) throws Exception {
    java.nio.file.Path path = Files.createTempFile("junix", ".sock");
    Files.delete(path);
    AFUNIXSocketAddress addr = AFUNIXSocketAddress.of(path);
    try (AFUNIXServerSocketChannel ssc = AFUNIXServerSocketChannel.open()) {
      ssc.bind(addr);
      AFUNIXSocketChannel client = AFUNIXSocketChannel.open(addr);
      AFUNIXSocketChannel server = ssc.accept();

      int size = 100 * 1024;
      byte[] payload = new byte[size];
      for (int i = 0; i < size; i++) payload[i] = (byte) (i % 251);

      Thread writer = new Thread(() -> {
        try {
          ByteBuffer wb = ByteBuffer.wrap(payload);
          while (wb.hasRemaining()) {
            int n = server.write(wb);
            if (n <= 0) Thread.sleep(10);
          }
        } catch (Exception e) { e.printStackTrace(); }
      });
      writer.start();

      ByteBuffer dst = directRead ? ByteBuffer.allocateDirect(size) : ByteBuffer.allocate(size);
      int total = 0;
      long deadline = System.currentTimeMillis() + 5000;
      int reads = 0;
      while (System.currentTimeMillis() < deadline) {
        int n = client.read(dst);
        reads++;
        if (n < 0) break;
        total += Math.max(n, 0);
        if (!dst.hasRemaining()) break;
      }
      byte[] received;
      if (directRead) {
        received = new byte[dst.position()];
        dst.duplicate().flip().get(received);
      } else {
        received = new byte[dst.position()];
        System.arraycopy(dst.array(), 0, received, 0, dst.position());
      }
      System.out.println(label + ": received=" + received.length + " payload=" + payload.length + " reads=" + reads + " MATCH=" + Arrays.equals(payload, received));
      if (!Arrays.equals(payload, received)) {
        int first = -1;
        for (int i = 0; i < Math.min(payload.length, received.length); i++) {
          if (payload[i] != received[i]) { first = i; break; }
        }
        System.out.println("  first mismatch at " + first);
        // detect repetition: compare chunk k*32768
        int chunk = 32768;
        for (int k = 1; k * chunk < received.length; k++) {
          boolean same = true;
          for (int j = 0; j < chunk; j++) {
            if (received[j] != received[k*chunk + j]) { same = false; break; }
          }
          System.out.println("  chunk " + k + " at " + (k*chunk) + " equals first chunk? " + same);
        }
      }
      server.close();
      client.close();
      writer.join();
    }
  }

  public static void main(String[] args) throws Exception {
    test("directRead", true);
    test("heapRead", false);
  }
}
