import java.nio.ByteBuffer;
import java.nio.file.Files;
import java.util.Arrays;

import org.newsclub.net.unix.AFUNIXServerSocketChannel;
import org.newsclub.net.unix.AFUNIXSocketChannel;
import org.newsclub.net.unix.AFUNIXSocketAddress;

public class Repro5 {
  static void test(String label, int size, int dstCapacity, int dstStartPos) throws Exception {
    java.nio.file.Path path = Files.createTempFile("junix", ".sock");
    Files.delete(path);
    AFUNIXSocketAddress addr = AFUNIXSocketAddress.of(path);
    try (AFUNIXServerSocketChannel ssc = AFUNIXServerSocketChannel.open()) {
      ssc.bind(addr);
      AFUNIXSocketChannel client = AFUNIXSocketChannel.open(addr);
      AFUNIXSocketChannel server = ssc.accept();
      server.configureBlocking(false);

      byte[] payload = new byte[size];
      for (int i = 0; i < size; i++) payload[i] = (byte) (i % 251);

      Thread writer = new Thread(() -> {
        try {
          ByteBuffer wb = ByteBuffer.wrap(payload);
          int loop = 0;
          while (wb.hasRemaining()) {
            int n = server.write(wb);
            if (n <= 0) { loop++; Thread.sleep(2); }
            if (loop > 500) throw new RuntimeException("stalled");
          }
          server.close(); // EOF
        } catch (Exception e) { e.printStackTrace(); }
      });
      writer.start();

      ByteBuffer dst = ByteBuffer.allocate(dstCapacity); // heap
      dst.position(dstStartPos); // start at non-zero position if requested
      int total = 0;
      long deadline = System.currentTimeMillis() + 5000;
      while (System.currentTimeMillis() < deadline) {
        int n = client.read(dst);
        if (n < 0) break;
        total += n;
        if (total >= size && !dst.hasRemaining()) {
          // refill for reading more
          byte[] tmp = new byte[dst.position()];
          System.arraycopy(dst.array(), 0, tmp, 0, dst.position());
          // We'll just accumulate into a byte list
          if (firstBuf == null) firstBuf = tmp;
          else {
            byte[] combined = new byte[firstBuf.length + tmp.length];
            System.arraycopy(firstBuf, 0, combined, 0, firstBuf.length);
            System.arraycopy(tmp, 0, combined, firstBuf.length, tmp.length);
            firstBuf = combined;
          }
          dst.clear();
          dst.position(dstStartPos);
        }
      }
      // collect remaining
      byte[] last = new byte[dst.position()];
      System.arraycopy(dst.array(), 0, last, 0, dst.position());
      byte[] received;
      if (firstBuf == null) {
        received = last;
      } else {
        received = new byte[firstBuf.length + last.length];
        System.arraycopy(firstBuf, 0, received, 0, firstBuf.length);
        System.arraycopy(last, 0, received, firstBuf.length, last.length);
      }
      System.out.println(label + ": size=" + size + " received=" + received.length + " MATCH=" + Arrays.equals(payload, received));
      writer.join();
      client.close();
    }
  }

  static byte[] firstBuf = null;

  public static void main(String[] args) throws Exception {
    firstBuf = null; test("smallDst(8192) start0  ", 100*1024, 8192, 0);
    firstBuf = null; test("smallDst(8192) start10 ", 100*1024, 8192, 10);
    firstBuf = null; test("largeDst(200K) start0  ", 100*1024, 200*1024, 0);
    firstBuf = null; test("largeDst(200K) start100", 100*1024, 200*1024, 100);
    firstBuf = null; test("largeData(2MB) start0  ", 2*1024*1024, 4096, 0);
  }
}
EOF
